import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 17
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
    ))

    header_index = None
    first_candidate = None
    for index, record in enumerate(records):
        if not any(field.strip() for field in record):
            continue
        if record == ["sep=", ""] or (
            len(record) == 1 and record[0].strip().lower() == "sep=;"
        ):
            continue
        if first_candidate is None:
            first_candidate = index
        if len(record) == expected_width:
            header_index = index
            break

    if header_index is None:
        header_index = first_candidate
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Give overflow fields their own columns rather than truncating values.
    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"extra_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
